param([Parameter(Mandatory=$true)][ValidateSet('focused-one','focused-plus-background')][string]$Mode,[switch]$Final)
$ErrorActionPreference='Stop'; $label='n16-'+$Mode+'-console-intel'; $name='274bot-BotTest-managed-panel-36825a9-'+$label
$run=Join-Path 'C:\Users\BotTest' ('274bot-runs\managed-panel-36825a9-'+$label); $task=Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue; $info=if($task){Get-ScheduledTaskInfo -TaskName $name}else{$null}; $completion=Join-Path $run 'completion.json'
$startup=@(); function Read-StartupLine([string]$line,[string]$path){if($line -notmatch '"event"\s*:\s*"startup"' -or $line -notmatch '"adapter_name"\s*:'){return};try{$f=$line.IndexOf('{');$l=$line.LastIndexOf('}');if($f -lt 0 -or $l -le $f){return};$o=$line.Substring($f,$l-$f+1)|ConvertFrom-Json;if($o.event -eq 'startup'){$script:startup+=[pscustomobject]@{path=$path;adapter_name=$o.adapter_name;requested_adapter_name=$o.requested_adapter_name;adapter_backend=$o.adapter_backend}}}catch{}}
if(Test-Path $run){foreach($receipt in @(Get-ChildItem $run -Recurse -File -Filter receipt.json -ErrorAction SilentlyContinue)){try{$r=Get-Content $receipt.FullName -Raw|ConvertFrom-Json;$raw=$r.run_dir}catch{continue};if($raw -and (Test-Path $raw)){foreach($f in @(Get-ChildItem $raw -Recurse -File -Include *.json,*.log -ErrorAction SilentlyContinue)){foreach($line in @(Get-Content $f.FullName -ErrorAction SilentlyContinue)){Read-StartupLine $line $f.FullName}}}}}
$result=[ordered]@{utc=[DateTime]::UtcNow.ToString('o');task=$name;mode=$Mode;count=16;adapter='Intel(R) Graphics';backgroundFps=if($Mode -eq 'focused-plus-background'){1}else{$null};taskState=if($task){[string]$task.State}else{'Missing'};lastTaskResult=if($info){$info.LastTaskResult}else{$null};completionPresent=(Test-Path $completion);startup=$startup;performanceAcceptance=$false};$result|ConvertTo-Json -Depth 6
if($Final){if(-not (Test-Path $completion)){throw 'Completion receipt missing'};$c=Get-Content $completion -Raw|ConvertFrom-Json;if($c.exit_code -ne 0){throw ('Diagnostic exit code '+$c.exit_code)};$requested='Intel(R) Graphics';if(@($startup|Where-Object {$_.adapter_name -eq $requested -and $_.requested_adapter_name -eq $requested}).Count -lt 1){throw 'No startup record proves requested adapter was selected'}}
